 static Map<String,Object> configurationRoot(){var r=new LinkedHashMap<String,Object>();r.put("id",TENANT);r.put("tenantId",TENANT);r.put("planId",ID);r.put("name","Synthetic organization");r.put("planName","Historical offer");r.put("slug","synthetic-clinic");r.put("kind","CLINIC");r.put("domain","HUMAN");r.put("status","SUSPENDED");r.put("timezone","America/Lima");r.put("cycle","MONTHLY");r.put("renewalDate","2028-02-29");r.put("createdAt","2026-11-04T00:00:00.123456Z");for(String k:List.of("planVersion","version","branchQuota","professionalQuota","specialtyQuota","includedBranches","includedProfessionals","includedSpecialties","maxBranches","maxProfessionals","maxSpecialties"))r.put(k,1);for(String k:List.of("baseMinor","branchMinor","professionalMinor"))r.put(k,0L);r.put("annualDiscount",0);r.put("kinds",List.of("CLINIC"));r.put("domains",List.of("HUMAN"));r.put("modules",List.of("CORE"));return r;}
 void configurationResult(boolean platform){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.ORGANIZATION_CONFIGURATION,inv.getArgument(0));var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(platform?null:TENANT,c.tenantId());assertEquals(ID,c.actorId());assertEquals(List.of(TENANT),Arrays.asList((Object[])inv.getRawArguments()[2]));var sets=new ArrayList<List<Map<String,Object>>>();sets.add(List.of(configurationRoot()));for(int i=0;i<7;i++)sets.add(List.of());return new SqlServerExecutor.Result(sets,List.of(0));});}
 @Test void configurationTenantAdmAndExplicitPlatformSadUseOneEightSetCall(){actor("ADM",false);configurationResult(false);var result=service.configuration(null);assertEquals(36,result.size());assertEquals(TENANT,result.get("id"));assertEquals(ID,result.get("planId"));for(String key:List.of("branches","areas","specialties","members","invoices"))assertEquals(List.of(),result.get(key));verify(access).roles("ADM");verify(access).tenant();verify(access,never()).platform();assertThrows(UnsupportedOperationException.class,result::clear);actor("SAD",true);configurationResult(true);assertEquals(TENANT,service.configuration(TENANT).get("id"));verify(access).platform();verify(executor,times(2)).execute(eq(SqlServerProcedure.ORGANIZATION_CONFIGURATION),any(),eq(TENANT));verifyNoInteractions(sql,identity);}
