 void writeResults(boolean platform){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(platform?null:TENANT,c.tenantId());assertEquals(ID,c.actorId());Object[] a=(Object[])inv.getRawArguments()[2];assertEquals(TENANT,a[0]);var p=inv.<SqlServerProcedure>getArgument(0);if(p==SqlServerProcedure.ORGANIZATION_SUBSCRIPTION_CHANGE || p==SqlServerProcedure.ORGANIZATION_SPECIALTIES_SAVE){var sets=new ArrayList<List<Map<String,Object>>>();var root=configurationRoot();root.put("status","ACTIVE");sets.add(List.of(root));for(int i=0;i<7;i++)sets.add(new ArrayList<>());if(p==SqlServerProcedure.ORGANIZATION_SUBSCRIPTION_CHANGE)sets.get(7).add(pendingInvoice((String)a[1]));if(p==SqlServerProcedure.ORGANIZATION_SPECIALTIES_SAVE){String sql;try(var in=getClass().getResourceAsStream("/db/sqlserver/V2__catalog_seed.sql")){sql=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}String line=sql.lines().filter(v->v.contains("VALUES(N'H_FAMILY',")).findFirst().orElseThrow();var chunks=java.util.regex.Pattern.compile("N'((?:''|[^'])*)'").matcher(line.substring(line.indexOf("CAST(N'")));var body=new StringBuilder();while(chunks.find())body.append(chunks.group(1).replace("''","'"));var profile=new tools.jackson.databind.ObjectMapper().readValue(body.toString(),Map.class);sets.get(3).add(new LinkedHashMap<>(Map.of("code","H_FAMILY","name",profile.get("name"),"domain","HUMAN","dental",false,"profile",profile)));}return new SqlServerExecutor.Result(sets,List.of());}var json=new tools.jackson.databind.ObjectMapper().readValue((String)a[2],Map.class);var row=new LinkedHashMap<String,Object>();row.put("id",a[1]);row.put("tenantId",TENANT);row.put("name",json.get("name"));if(p==SqlServerProcedure.ORGANIZATION_BRANCH_SAVE){row.put("address",json.get("address"));row.put("external",json.get("external"));row.put("active",json.get("active"));}else{assertEquals(SqlServerProcedure.ORGANIZATION_AREA_SAVE,p);row.put("branchId",json.get("branchId"));row.put("specialties",json.get("specialties"));}return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());});}
 @Test void fourWritesUseRealStoreForAdmAndExplicitSadWithoutConfigurationRead(){for(boolean platform:List.of(false,true)){actor(platform?"SAD":"ADM",platform);writeResults(platform);String target=platform?TENANT:null;assertEquals("ACTIVE",service.subscription(target,new com.mavric.health.saas.domain.Requests.Subscription(ID,"MONTHLY",1,1,1)).get("status"));assertEquals(false,service.branch(target,null,new com.mavric.health.organization.domain.Requests.Branch("Sede","",false,false)).get("active"));assertEquals(ID,service.area(target,null,new com.mavric.health.organization.domain.Requests.Area(ID,"Consulta",Set.of("H_FAMILY"))).get("branchId"));assertEquals(36,service.specialties(target,new com.mavric.health.organization.domain.Requests.Specialties(Set.of("H_FAMILY"))).size());}verify(executor,times(2)).execute(eq(SqlServerProcedure.ORGANIZATION_SUBSCRIPTION_CHANGE),any(),eq(TENANT),anyString(),anyString());verify(executor,times(2)).execute(eq(SqlServerProcedure.ORGANIZATION_BRANCH_SAVE),any(),eq(TENANT),anyString(),anyString(),eq(true));verify(executor,times(2)).execute(eq(SqlServerProcedure.ORGANIZATION_AREA_SAVE),any(),eq(TENANT),anyString(),anyString(),eq(true));verify(executor,times(2)).execute(eq(SqlServerProcedure.ORGANIZATION_SPECIALTIES_SAVE),any(),eq(TENANT),anyString());verify(executor,never()).execute(eq(SqlServerProcedure.ORGANIZATION_CONFIGURATION),any(),any(Object[].class));verify(access,times(4)).platform();verify(access,times(4)).roles("ADM");verify(access,never()).branch(anyString());verifyNoInteractions(sql,identity);}
 @Test void writeAuthorityAndNullInputsPrecedeAnyEffects(){var work=List.<Runnable>of(()->service.subscription(null,null),()->service.branch(null,null,null),()->service.area(null,null,null),()->service.specialties(null,null));for(Runnable op:work)assertEquals(500,assertThrows(ApiException.class,op::run).status);actor("PRO",false);for(Runnable op:work)assertEquals(403,assertThrows(ApiException.class,op::run).status);actor("ADM",false);for(Runnable op:work)assertEquals(400,assertThrows(ApiException.class,op::run).status);assertEquals(403,assertThrows(ApiException.class,()->service.subscription(TENANT,null)).status);actor("SOP",true);assertEquals(403,assertThrows(ApiException.class,()->service.branch(TENANT,null,null)).status);actor("SAD",true);request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.area(TENANT,null,null)).status);verifyNoInteractions(sql,identity,executor);}
