 @Test void explicitSadSubscriptionPreservesSuspendedStateReturnedBySp(){actor("SAD",true);when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.ORGANIZATION_SUBSCRIPTION_CHANGE,inv.getArgument(0));assertNull(inv.<SqlServerContext>getArgument(1).tenantId());var sets=new ArrayList<List<Map<String,Object>>>();sets.add(List.of(configurationRoot()));for(int i=0;i<7;i++)sets.add(new ArrayList<>());sets.get(7).add(pendingInvoice((String)((Object[])inv.getRawArguments()[2])[1]));return new SqlServerExecutor.Result(sets,List.of());});var result=service.subscription(TENANT,new com.mavric.health.saas.domain.Requests.Subscription(ID,"MONTHLY",1,1,1));assertEquals("SUSPENDED",result.get("status"));verify(executor,times(1)).execute(eq(SqlServerProcedure.ORGANIZATION_SUBSCRIPTION_CHANGE),any(),eq(TENANT),anyString(),anyString());verifyNoInteractions(sql,identity);}

 static Map<String,Object> pendingInvoice(String id){var row=new LinkedHashMap<String,Object>();row.put("id",id);row.put("tenantId",TENANT);row.put("amountMinor",0L);row.put("currency","PEN");row.put("cycle","MONTHLY");row.put("status","PENDING");row.put("createdAt","2026-11-04T00:00:01.123456Z");row.put("paidAt",null);return row;}

 final class MemberFlow {
  final org.springframework.security.crypto.password.PasswordEncoder encoder=mock(org.springframework.security.crypto.password.PasswordEncoder.class);final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> binds=new ArrayList<>();final OrganizationService real;String user;String clinicalDomain;
  MemberFlow(com.mavric.health.organization.domain.Requests.Member input,String failAt){var settings=new Settings("health.localhost","http://health.localhost",12,null);var realIdentity=new IdentityService(new SqlServerIdentityStore(executor,manager),access,encoder,settings);real=new OrganizationService(access,new SqlServerOrganizationStore(executor,manager),realIdentity);when(encoder.encode("synthetic-password")).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());if(failAt.equals("ENCODER"))throw new IllegalStateException("private encoder");return "synthetic-hash";});user=input.userId();clinicalDomain=input.user()==null?null:input.user().domain();when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var p=inv.<SqlServerProcedure>getArgument(0);var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertEquals(request.getAttribute("health.tenant")==null?null:TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());Object[] a=(Object[])inv.getRawArguments()[2];calls.add(p);binds.add(Arrays.asList(a.clone()));if(failAt.equals(p.name()))throw new RuntimeException(new java.sql.SQLException("private driver",null,51003));if(p==SqlServerProcedure.USER_CREATE){user=(String)a[0];assertEquals(UUID.fromString(user).toString(),user);assertEquals("Synthetic",a[1]);assertEquals("qa@example.test",a[2]);assertEquals("synthetic-hash",a[3]);assertEquals(input.user().domain(),a[4]);assertEquals(input.user().credential(),a[5]);return new SqlServerExecutor.Result(List.of(),List.of());}assertEquals(SqlServerProcedure.ORGANIZATION_MEMBER_SAVE,p);assertEquals(TENANT,a[0]);assertEquals(user,a[1]);var json=new tools.jackson.databind.ObjectMapper().readValue((String)a[2],Map.class);assertEquals(Set.of("roles","status","branches","specialties"),json.keySet());assertEquals(new HashSet<>(input.roles()),new HashSet<>((List<?>)json.get("roles")));assertEquals(new HashSet<>(input.branches()),new HashSet<>((List<?>)json.get("branches")));assertEquals(new HashSet<>(input.specialties()),new HashSet<>((List<?>)json.get("specialties")));assertFalse(((String)a[2]).contains("qa@example.test"));assertFalse(((String)a[2]).contains("synthetic-password"));assertFalse(((String)a[2]).contains("synthetic-hash"));var row=new LinkedHashMap<String,Object>();row.put("id",failAt.equals("ROW")?ID:user);row.put("name","Synthetic");row.put("email","qa@example.test");row.put("clinicalDomain",clinicalDomain);row.put("roles",new ArrayList<>(input.roles()));row.put("status",input.status());row.put("owner",false);row.put("credential","private credential");row.put("passwordHash","private hash");row.put("tokenHash","private token");return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());});}
 }
