 @Test void memberMissingRequest401SopHostMismatchAndForeignTargetStopBeforeIdentity(){assertEquals(500,assertThrows(ApiException.class,()->service.member(null,memberInput(true,true,"HUMAN"))).status);actor("ADM",false);doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.member(null,null)).status);actor("SOP",true);assertEquals(403,assertThrows(ApiException.class,()->service.member(TENANT,null)).status);actor("ADM",false);assertEquals(403,assertThrows(ApiException.class,()->service.member(TENANT,null)).status);request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.member(null,null)).status);actor("ADM",false);request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.member(null,null)).status);verifyNoInteractions(executor,identity,sql);}
 @Test void realUserCreationMemberMappingAndCommitFailuresCannotCommitPartialUnit(){actor("ADM",false);for(String stage:List.of("ENCODER","USER_CREATE","ORGANIZATION_MEMBER_SAVE","ROW","COMMIT")){manager.events.clear();var input=memberInput(true,true,"HUMAN");var f=new MemberFlow(input,stage);manager.failCommit=stage.equals("COMMIT");var error=assertThrows(ApiException.class,()->f.real.member(null,input));assertEquals(stage.equals("USER_CREATE") || stage.equals("ORGANIZATION_MEMBER_SAVE")?409:500,error.status);assertFalse(error.toString().contains("private"));if(stage.equals("ENCODER"))assertTrue(f.calls.isEmpty());else if(stage.equals("USER_CREATE"))assertEquals(List.of(SqlServerProcedure.USER_CREATE),f.calls);else assertEquals(List.of(SqlServerProcedure.USER_CREATE,SqlServerProcedure.ORGANIZATION_MEMBER_SAVE),f.calls);if(!stage.equals("COMMIT")){assertFalse(manager.events.contains("commit"));assertEquals("rollback",manager.events.getLast());}assertEquals(ID,((Actor)request.getAttribute("health.actor")).id());}verifyNoInteractions(identity,sql);}
 @Test void realNewIdentityAndMembershipJoinOuterCancellationWithoutInnerCommit(){actor("ADM",false);var input=memberInput(true,true,"HUMAN");var f=new MemberFlow(input,"");assertThrows(RuntimeException.class,()->manager.outer(()->{var out=f.real.member(null,input);assertEquals(7,out.size());assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("synthetic cancellation");}));assertEquals(List.of(SqlServerProcedure.USER_CREATE,SqlServerProcedure.ORGANIZATION_MEMBER_SAVE),f.calls);assertEquals(List.of("begin:0","rollback"),manager.events);verifyNoInteractions(sql,identity);}
